#!/usr/bin/env bash\n# uptime_emoji.sh - Report system uptime with an emoji\n\n# Optional argument: path to uptime file (default /proc/uptime)\nUPTIME_FILE=\"${1:-/proc/uptime}\"\n\nif [[ ! -r \"$UPTIME_FILE\" ]]; then\n  echo \"Error: Cannot read $UPTIME_FILE\" >&2\n  exit 1\nfi\n\n# Read the first number (seconds)\nread -r UPTIME_SECONDS _ < \"$UPTIME_FILE\"\n\n# Calculate days, hours, minutes\nTOTAL_SECONDS=${UPTIME_SECONDS%.*}\nDAYS=$(( TOTAL_SECONDS / 86400 ))\nHOURS=$(( (TOTAL_SECONDS % 86400) / 3600 ))\nMINUTES=$(( (TOTAL_SECONDS % 3600) / 60 ))\n\n# Choose emoji\nif (( DAYS < 1 )); then\n  EMOJI=\"🌱\"\nelif (( DAYS <= 7 )); then\n  EMOJI=\"🌿\"\nelse\n  EMOJI=\"🌳\"\nfi\n\necho \"Uptime: $DAYS days $HOURS hours $MINUTES minutes $EMOJI\"
